+{
+    /// <summary>
+    /// A text form of a value that does not depend on Newtonsoft.Json, the machine, or iteration
+    /// order: members in ordinal order, decimals with their scale, doubles round-trippable, dates
+    /// with their kind, sets and dictionaries sorted, and the runtime type where it differs from
+    /// the declared one.
+    /// </summary>
+    internal static class OfframpObjectDump
+    {
+        private const int MaxDepth = 8;
+
+        public static string Write(object value)
+        {
+            var text = value as string;
+            if (text != null)
+            {
