+        private static void Write(StringBuilder builder, object value, Type declared, int depth, List<object> path)
+        {
+            if (value == null)
+            {
+                builder.Append("null");
+                return;
+            }
+
+            var type = value.GetType();
+            var scalar = Scalar(value);
+            if (scalar != null)
+            {
+                builder.Append(scalar).Append(Runtime(type, declared));
+                return;
+            }
+
+            if (type.FullName != null && type.FullName.StartsWith("Newtonsoft.Json.Linq.", StringComparison.Ordinal))
+            {
+                builder.Append(OfframpProbe.Normalize(value.ToString())).Append(Runtime(type, declared));
+                return;
+            }
+
+            if (depth >= MaxDepth)
+            {
+                builder.Append("...");
+                return;
+            }
+
+            if (!type.IsValueType && path.Any(p => ReferenceEquals(p, value)))
+            {
+                builder.Append("(cycle)");
+                return;
+            }
+
+            path.Add(value);
+            try
+            {
+                var indent = new string(' ', 2 * (depth + 1));
+                var dictionary = value as IDictionary;
+                var sequence = value as IEnumerable;
+                if (dictionary != null)
+                {
+                    var entries = new List<KeyValuePair<string, object>>();
+                    foreach (DictionaryEntry entry in dictionary)
+                    {
+                        entries.Add(new KeyValuePair<string, object>(Key(entry.Key), entry.Value));
+                    }
+
+                    builder.Append('{').Append(entries.Count.ToString(CultureInfo.InvariantCulture)).Append('}').Append(Runtime(type, declared));
+                    foreach (var entry in entries.OrderBy(e => e.Key, StringComparer.Ordinal))
+                    {
+                        builder.Append('\n').Append(indent).Append(entry.Key).Append(": ");
+                        Write(builder, entry.Value, null, depth + 1, path);
+                    }
+                }
+                else if (sequence != null)
+                {
+                    var items = new List<string>();
+                    foreach (var item in sequence)
+                    {
+                        var inner = new StringBuilder();
+                        Write(inner, item, null, depth + 1, path);
