+        private static string Scalar(object value)
+        {
+            if (value is bool)
+            {
+                return (bool)value ? "true" : "false";
+            }
+
+            if (value is decimal)
+            {
+                return ((decimal)value).ToString(CultureInfo.InvariantCulture);
+            }
+
+            if (value is double)
+            {
+                var number = (double)value;
+                return number == 0 && double.IsNegativeInfinity(1 / number) ? "-0" : number.ToString("R", CultureInfo.InvariantCulture);
+            }
+
+            if (value is float)
+            {
+                var number = (float)value;
+                return number == 0 && float.IsNegativeInfinity(1 / number) ? "-0" : number.ToString("R", CultureInfo.InvariantCulture);
+            }
+
+            if (value is DateTime)
+            {
+                var date = (DateTime)value;
+                return date.Kind == DateTimeKind.Local
+                    ? date.ToUniversalTime().ToString("o", CultureInfo.InvariantCulture) + " (Local)"
+                    : date.ToString("o", CultureInfo.InvariantCulture) + " (" + date.Kind + ")";
+            }
+
+            if (value is DateTimeOffset)
+            {
+                return ((DateTimeOffset)value).ToString("o", CultureInfo.InvariantCulture);
+            }
+
+            if (value is TimeSpan)
+            {
+                return ((TimeSpan)value).ToString("c", CultureInfo.InvariantCulture);
+            }
+
+            if (value is Guid)
+            {
+                return ((Guid)value).ToString("D");
+            }
+
+            if (value is Enum)
+            {
+                var name = Enum.GetName(value.GetType(), value);
+                return (name ?? "(no name)") + " = " + Convert.ToInt64(value, CultureInfo.InvariantCulture).ToString(CultureInfo.InvariantCulture);
+            }
+
+            var text = value as string;
+            if (text != null)
+            {
+                return Quote(text);
+            }
+
+            if (value is char)
+            {
+                return Quote(value.ToString());
+            }
+
+            var bytes = value as byte[];
+            if (bytes != null)
+            {
+                return "bytes[" + bytes.Length.ToString(CultureInfo.InvariantCulture) + "] " + Convert.ToBase64String(bytes);
+            }
+
+            var uri = value as Uri;
+            if (uri != null)
+            {
+                return uri.OriginalString;
+            }
+
+            var type = value as Type;
+            if (type != null)
+            {
+                return type.FullName;
+            }
