+        {
+            var scalar = key == null ? "null" : Scalar(key);
+            return scalar ?? Convert.ToString(key, CultureInfo.InvariantCulture);
+        }
+
+        private static string Quote(string text)
+        {
+            var builder = new StringBuilder("\"");
+            foreach (var c in text)
+            {
+                switch (c)
+                {
+                    case '"': builder.Append("\\\""); break;
+                    case '\\': builder.Append("\\\\"); break;
+                    case '\n': builder.Append("\\n"); break;
+                    case '\r': builder.Append("\\r"); break;
+                    case '\t': builder.Append("\\t"); break;
+                    default:
+                        if (c < ' ' || c > '~')
+                        {
+                            builder.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
+                        }
+                        else
+                        {
+                            builder.Append(c);
+                        }
+
+                        break;
+                }
+            }
+
+            return builder.Append('"').ToString();
+        }
+
+        private static IEnumerable<MemberInfo> Members(Type type)
+        {
+            var properties = type.GetProperties(BindingFlags.Public | BindingFlags.Instance)
+                .Where(p => p.CanRead && p.GetIndexParameters().Length == 0)
+                .Cast<MemberInfo>();
+            var fields = type.GetFields(BindingFlags.Public | BindingFlags.Instance).Cast<MemberInfo>();
+            return properties.Concat(fields).GroupBy(m => m.Name).Select(g => g.First()).OrderBy(m => m.Name, StringComparer.Ordinal);
+        }
+
+        private static bool IsSet(Type type)
+        {
+            return type.GetInterfaces().Any(i => i.IsGenericType && (i.GetGenericTypeDefinition().FullName == "System.Collections.Generic.ISet`1"
+                || i.GetGenericTypeDefinition().FullName == "System.Collections.Immutable.IImmutableSet`1"));
+        }
+
+        /// <summary>The runtime type, when the declared type does not already say it.</summary>
+        private static string Runtime(Type type, Type declared)
+        {
+            if (declared == null || declared == type || Nullable.GetUnderlyingType(declared) == type)
+            {
+                return "";
+            }
+
+            return " (" + Name(type) + ")";
+        }
+
+        private static string Name(Type type)
+        {
+            if (!type.IsGenericType)
+            {
+                return type.FullName ?? type.Name;
+            }
+
+            var definition = type.GetGenericTypeDefinition().FullName ?? type.Name;
+            var tick = definition.IndexOf('`');
+            return (tick < 0 ? definition : definition.Substring(0, tick)) + "<" + string.Join(", ", type.GetGenericArguments().Select(Name)) + ">";
+        }
+    }
+}
